class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_mib = monthly_limit_mib
        self.monthly_files = {}  # {month: {filename: size_bytes}}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("File size cannot be zero")

        # Check if file already exists in this month
        if month not in self.monthly_files:
            self.monthly_files[month] = {}

        if name in self.monthly_files[month]:
            # File already uploaded this month, no action needed
            return

        # Calculate current usage for this month
        current_usage = sum(self.monthly_files[month].values()) if month in self.monthly_files else 0

        # Check if adding this file would exceed the limit
        new_total = current_usage + size_bytes
        limit_bytes = self.monthly_limit_mib * 1024 * 1024

        if new_total > limit_bytes:
            raise ValueError("Upload would exceed monthly quota")

        # Add the file
        self.monthly_files[month][name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        if month in self.monthly_files and name in self.monthly_files[month]:
            del self.monthly_files[month][name]

    def used_bytes(self, month: str) -> int:
        if month not in self.monthly_files:
            return 0
        return sum(self.monthly_files[month].values())
